function testBuildPrompt() {
  console.log(buildPrompt({ Tomato: 3.1, Bean: 2.6 }))
}

function buildPrompt(totals) {
  const lines = Object.entries(totals).map(([crop, kg]) => `${crop}: ${kg} kg`)
  const total = Object.values(totals).reduce((sum, kg) => sum + kg, 0)
  return ["Write a short newsletter paragraph using only these numbers:", ...lines, `Total: ${total.toFixed(1)} kg`].join("\n")
}
